from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(x: int) -> int:
        while x in jump:
            x = jump[x]
        return x

    def step(p: int, r: int) -> int:
        q = p + r
        if q > n:
            q = 2 * n - p - r
        return resolve(q)

    # Explore states reachable from the start (cell 0), excluding the terminal cell n
    start = 0
    trans = {}
    reach = [start]
    seen = {start}
    i = 0
    while i < len(reach):
        x = reach[i]
        i += 1
        nxt = [step(x, r) for r in range(1, m + 1)]
        trans[x] = nxt
        for t in nxt:
            if t != n and t not in seen:
                seen.add(t)
                reach.append(t)

    # If some reachable state cannot reach n, the game may never end
    good = set()
    changed = True
    while changed:
        changed = False
        for x in reach:
            if x not in good and any(t == n or t in good for t in trans[x]):
                good.add(x)
                changed = True
    if len(good) != len(reach):
        return None

    # Solve E[x] = 1 + (1/m) * sum E[t] over reachable non-terminal states
    k = len(reach)
    idx = {x: j for j, x in enumerate(reach)}
    A = [[Fraction(0)] * (k + 1) for _ in range(k)]
    for x in reach:
        row = idx[x]
        A[row][row] += 1
        for t in trans[x]:
            if t != n:
                A[row][idx[t]] -= Fraction(1, m)
        A[row][k] = Fraction(1)

    # Gauss-Jordan elimination with exact fractions
    for c in range(k):
        piv = next(r for r in range(c, k) if A[r][c] != 0)
        A[c], A[piv] = A[piv], A[c]
        inv = 1 / A[c][c]
        A[c] = [v * inv for v in A[c]]
        for r in range(k):
            if r != c and A[r][c] != 0:
                f = A[r][c]
                A[r] = [a - f * b for a, b in zip(A[r], A[c])]

    ans = A[idx[start]][k]
    return [ans.numerator, ans.denominator]
